    "case.guideYou.facts": [{"label": "Company", "value": "Antipoff IT (custom software development)"}, {"label": "Product", "value": "Guide You — iOS app for Moscow guides and tourists"}, {"label": "Role", "value": "UX/UI designer in a product team"}, {"label": "Duration", "value": "2 months, 2022"}],
    "case.guideYou.alt01": "Cover: the Guide You logo and title, subtitle and a phone with the tour catalog",
